import{_ as a,c as t,o as i,aj as n}from"./chunks/framework.e3UxQEvm.js";const g=JSON.parse('{"title":"Messages","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/messages.md","filePath":"architecture/messages.md"}'),o={name:"architecture/messages.md"};function s(r,e,c,d,h,l){return i(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="messages" tabindex="-1">Messages <a class="header-anchor" href="#messages" aria-label="Permalink to “Messages”">​</a></h1><p>Built-in messaging is based on the <a href="https://solid.github.io/chat/" target="_blank" rel="noreferrer">Chat Client-to-Client (C2C) specification</a> for data storage, and Linked Data Notifications (LDN) or ActivityPub for notifications.</p><h2 id="protocol" tabindex="-1">Protocol <a class="header-anchor" href="#protocol" aria-label="Permalink to “Protocol”">​</a></h2><h3 id="starting-a-new-chat" tabindex="-1">Starting a new chat <a class="header-anchor" href="#starting-a-new-chat" aria-label="Permalink to “Starting a new chat”">​</a></h3><p>One person creates a chat channel in their Pod, and give Read + Append access to one or all invited participants. This chat channel owner also writes a message to the channel, and sends a <code>as:Invite</code> notification to all invitees&#39; inboxes.</p><h3 id="inbox" tabindex="-1">Inbox <a class="header-anchor" href="#inbox" aria-label="Permalink to “Inbox”">​</a></h3><p>Inboxes can be as follows:</p><ul><li>public append directory on Solid Pod, linked from the person&#39;s webid profile document with <code>ldp:inbox</code> (not recommended, not secure, as data validation and sender authentication are missing from Solid server implementations)</li><li>authenticated agent append directory on Solid Pod, linked from the person&#39;s webid profile document with <code>ldp:inbox</code> (safer, but not perfect)</li><li>hospex community members-only append directory on Solid Pod, linked from the hospex profile document with <code>ldp:inbox</code> (even safer, but not perfect)</li><li>a dedicated inbox endpoint capable of authenticating, verifying, and validating the received notifications. This endpoint service then saves the authenticated and valid notification to a dedicated storage on the person&#39;s pod for the app to process. (safest, most complex)</li></ul><p>The discovery and POSTing the notification is independent of the particular inbox implementations above.</p><h3 id="joining-a-chat" tabindex="-1">Joining a chat <a class="header-anchor" href="#joining-a-chat" aria-label="Permalink to “Joining a chat”">​</a></h3><p>Upon receiving an <code>as:Invite</code> notification, the invitee can choose whether to accept or reject the invitation to chat.</p><p>If they <strong>reject</strong>, the invite and message notifications get deleted, a <code>as:Reject</code> notification MAY be sent back to other chat participants.</p><p>If they <strong>accept</strong>, they append themself as a participant to the chat, send <code>as:Accept</code> to all other participants, and proceed with sending messages.</p><h3 id="sending-a-message" tabindex="-1">Sending a message <a class="header-anchor" href="#sending-a-message" aria-label="Permalink to “Sending a message”">​</a></h3><p>To send a message, person must attach it to the chat according to the chat specification, and send a notification to all other participants.</p><p>Message SHOULD be signed with the message author&#39;s key.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to “Notifications”">​</a></h3><ul><li><code>Invite</code> is an ActivityStreams notification with actor, object - the chat URI, and target, the person being invited</li><li><code>Create</code>, <code>Update</code>, <code>Delete</code> - actor must match the authenticated user, object is the URI of the message, inReplyTo is URI of the message being replied to (if any), and context - the chat URI</li></ul><h3 id="unread-messages" tabindex="-1">Unread messages <a class="header-anchor" href="#unread-messages" aria-label="Permalink to “Unread messages”">​</a></h3><p>The messages that have corresponding <code>Create</code> notification in the inbox SHOULD be marked in the UI as unread. When the message gets read, the corresponding notification SHOULD be deleted. The UI MAY keep showing the message as unread until the next refresh, or change to read. Particular way of distinguishing unread and read messages is not mandated.</p><h3 id="discovery" tabindex="-1">Discovery <a class="header-anchor" href="#discovery" aria-label="Permalink to “Discovery”">​</a></h3><p>Every participant adds the chat URI into their private type index.</p>',22)])])}const m=a(o,[["render",s]]);export{g as __pageData,m as default};
